    ) -> Double {
        guard clip.source.hasSourceBound else { return clip.speed }
        return clip.actions.compactMap(\.end.speed)
            .filter(\.isFinite)
            .map { Swift.min(Swift.max($0, limits.min), limits.max) }
            .reduce(clip.speed, Swift.max)
    }

